required = {s.strip().lower() for s in input().split(',') if s.strip()}
allowed = input().strip().upper()
allowed_set = None if allowed == 'ANY' else {c.strip() for c in allowed.split(',')}
n = int(input())

eligible = []
for _ in range(n):
    name, country, latency, price, services = input().split()
    offered = {s.lower() for s in services.split(',')}
    if allowed_set is not None and country.upper() not in allowed_set:
        continue
    if not required <= offered:
        continue
    eligible.append((int(latency), int(price), name))

print('Eligible regions: ' + str(len(eligible)))
if not eligible:
    print('NO SUITABLE REGION')
else:
    latency, price, name = min(eligible)
    print(f'Selected: {name} (latency {latency} ms, price index {price})')

import re
import sys

lines = sys.stdin.read().splitlines()

def compile_pattern(pattern, ignore_case):
    parts = []
    for ch in pattern:
        if ch == '*':
            parts.append('.*')
        elif ch == '?':
            parts.append('.')
        else:
            parts.append(re.escape(ch))
    flags = re.IGNORECASE if ignore_case else 0
    return re.compile('^' + ''.join(parts) + '$', flags)

n = int(lines[0])
statements = []
for line in lines[1:1 + n]:
    action, resource = line.split()
    statements.append((compile_pattern(action, True), compile_pattern(resource, False)))

m = int(lines[1 + n])
for line in lines[2 + n:2 + n + m]:
    action, resource = line.split()
    allowed = any(a.match(action) and r.match(resource) for a, r in statements)
    print(action + ' -> ' + ('ALLOWED' if allowed else 'DENIED'))
